sp_widget.css:
.tracker-card {
  background: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.05);
  border: 1px solid #e2e8f0;
  overflow: hidden;

  .tracker-header {
    padding: 16px 20px;
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    display: flex;
    justify-content: space-between;
    align-items: center;

    .tracker-title {
      font-size: 16px;
      font-weight: 700;
      color: #1e293b;
      span { color: #2563eb; }
    }
  }

  .status-badge {
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;

    &.badge-approved { background: #dcfce7; color: #15803d; }
    &.badge-rejected { background: #fee2e2; color: #b91c1c; }
    &.badge-pending { background: #fef3c7; color: #b45309; }
  }

  .tracker-body {
    padding: 30px 20px;
  }

  .stepper-wrapper {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    position: relative;

    .step-item {
      flex: 1;
      text-align: center;
      position: relative;

      .step-line {
        position: absolute;
        top: 22px;
        left: 50%;
        width: 100%;
        height: 3px;
        background: #e2e8f0;
        z-index: 1;
      }

      .step-circle {
        position: relative;
        z-index: 2;
        width: 44px;
        height: 44px;
        border-radius: 50%;
        background: #ffffff;
        border: 2px solid #cbd5e1;
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto 12px auto;
        font-size: 16px;
        color: #94a3b8;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      }

      .step-role {
        font-weight: 700;
        font-size: 13px;
        color: #334155;
      }

      .step-user {
        font-size: 12px;
        color: #64748b;
        margin: 2px 0 6px;
      }

      .step-tag {
        display: inline-block;
        font-size: 11px;
        font-weight: 600;
        padding: 2px 8px;
        border-radius: 6px;
        background: #f1f5f9;
        color: #64748b;
      }

      /* Dynamic State Styling */
      &.is-approved {
        .step-line { background: #22c55e; }
        .step-circle {
          background: #22c55e;
          border-color: #22c55e;
          color: #ffffff;
          box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.2);
        }
        .step-tag { background: #dcfce7; color: #15803d; }
      }

      &.is-pending {
        .step-circle {
          background: #f59e0b;
          border-color: #f59e0b;
          color: #ffffff;
          box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.2);
        }
        .step-tag { background: #fef3c7; color: #b45309; }
      }

      &.is-rejected {
        .step-line { background: #ef4444; }
        .step-circle {
          background: #ef4444;
          border-color: #ef4444;
          color: #ffffff;
          box-shadow: 0 0 0 4px rgba(239, 68, 68, 0.2);
        }
        .step-tag { background: #fee2e2; color: #b91c1c; }
      }

      &.is-na {
        .step-circle {
          background: #f8fafc;
          border-color: #e2e8f0;
          color: #cbd5e1;
        }
      }
    }
  }

  .rejection-box {
    margin-top: 25px;
    padding: 12px 16px;
    background: #fef2f2;
    border-left: 4px solid #ef4444;
    border-radius: 4px;
    color: #991b1b;
    font-size: 13px;
  }
}

.empty-selection-card {
  background: #ffffff;
  border: 2px dashed #cbd5e1;
  border-radius: 12px;
  padding: 40px 20px;
  text-align: center;
  color: #64748b;
  p { margin-top: 10px; font-weight: 500; }
}

sp_widget.script:
(function() {
    data.hasRecord = false;
    data.approvers = [];

    var inputTable = (typeof input !== 'undefined' && input) ? input.table : null;
    var inputRecordId = (typeof input !== 'undefined' && input) ? input.record_id : null;

    var targetId = $sp.getParameter('sys_id') || inputRecordId;
    var targetTable = $sp.getParameter('table') || inputTable || 'x_1983287_studen_0_leave_request';

    if (!targetId) return;

    var reqGR = new GlideRecord(targetTable);
    if (reqGR.get(targetId)) {
        data.hasRecord = true;
        data.record_type = (targetTable.indexOf('leave') > -1) ? 'Leave' : ((targetTable.indexOf('od') > -1) ? 'On-Duty (OD)' : 'Grievance');
        data.record_number = reqGR.getValue('number') || reqGR.getDisplayValue();
        data.overall_status = reqGR.getValue('status') || 'Submitted';
        data.rejection_reason = reqGR.isValidField('rejection_reason') ? reqGR.getValue('rejection_reason') : '';

        var stuProfile = reqGR.student.getRefRecord();
        var isValidStu = stuProfile.isValidRecord();

        function normalizeStatus(val) {
            if (!val) return 'Pending';
            var s = String(val).toLowerCase();
            if (s === 'approved') return 'Approved';
            if (s === 'rejected') return 'Rejected';
            if (s === 'not required' || s === 'not_required') return 'Not Required';
            return 'Pending';
        }

        // ==========================================
        // 1. LEAVE & OD REQUEST TRACKING PIPELINE
        // ==========================================
        if (targetTable.indexOf('grievance') === -1) {
            var isHosteller = isValidStu && (stuProfile.getValue('accommodation_type') === 'Hosteller');

            var mStatus = normalizeStatus(reqGR.getValue('mentor_approval'));
            var aStatus = normalizeStatus(reqGR.getValue('advisor_approval'));
            var hStatus = normalizeStatus(reqGR.getValue('hod_approval'));
            var wStatus = isHosteller ? normalizeStatus(reqGR.getValue('warden_approval')) : 'Not Required';

            // Auto-align overall status if all required approvers approved
            if (!isHosteller && mStatus === 'Approved' && aStatus === 'Approved' && hStatus === 'Approved') {
                data.overall_status = 'Approved';
            } else if (isHosteller && mStatus === 'Approved' && aStatus === 'Approved' && hStatus === 'Approved' && wStatus === 'Approved') {
                data.overall_status = 'Approved';
            }

            // Stage 1: Mentor
            data.approvers.push({
                role: 'Mentor',
                role_icon: 'fa-user',
                status: mStatus,
                person_name: isValidStu && stuProfile.mentor ? stuProfile.mentor.getDisplayValue() : 'Assigned Mentor'
            });

            // Stage 2: Class Advisor
            data.approvers.push({
                role: 'Class Advisor',
                role_icon: 'fa-graduation-cap',
                status: aStatus,
                person_name: isValidStu && stuProfile.class_advisor ? stuProfile.class_advisor.getDisplayValue() : 'Class Advisor'
            });

            // Stage 3: HOD
            var hodName = 'HOD';
            if (isValidStu) {
                if (stuProfile.hod) hodName = stuProfile.hod.getDisplayValue();
                else if (stuProfile.department && stuProfile.department.hod) hodName = stuProfile.department.hod.getDisplayValue();
            }
            data.approvers.push({
                role: 'HOD',
                role_icon: 'fa-university',
                status: hStatus,
                person_name: hodName
            });

            // Stage 4: Warden
            data.approvers.push({
                role: 'Warden',
                role_icon: 'fa-building',
                status: wStatus,
                person_name: isHosteller ? (stuProfile.warden ? stuProfile.warden.getDisplayValue() : 'Hostel Warden') : 'Day Scholar'
            });
        } 
        // ==========================================
        // 2. GRIEVANCE REDRESSAL PIPELINE
        // ==========================================
        else {
            var gStatus = (reqGR.getValue('status') || 'Open').toLowerCase();
            var assignedToName = reqGR.assigned_to ? reqGR.assigned_to.getDisplayValue() : 'Pending Assignment';

            // Stage 1: Logged / Submitted
            data.approvers.push({
                role: 'Submitted',
                role_icon: 'fa-file-text-o',
                status: 'Approved',
                person_name: 'System Logged'
            });

            // Stage 2: Assigned Authority
            data.approvers.push({
                role: 'Assigned To',
                role_icon: 'fa-user-secret',
                status: (reqGR.assigned_to) ? 'Approved' : 'Pending',
                person_name: assignedToName
            });

            // Stage 3: In Review / Action
            var inReviewStatus = (gStatus === 'in progress' || gStatus === 'investigating' || gStatus === 'resolved' || gStatus === 'closed') ? 'Approved' : (reqGR.assigned_to ? 'Pending' : 'Pending');
            data.approvers.push({
                role: 'Under Review',
                role_icon: 'fa-search',
                status: inReviewStatus,
                person_name: 'Committee'
            });

            // Stage 4: Resolution
            var resStatus = (gStatus === 'resolved' || gStatus === 'closed') ? 'Approved' : 'Pending';
            data.approvers.push({
                role: 'Resolved',
                role_icon: 'fa-check-circle',
                status: resStatus,
                person_name: reqGR.getValue('resolution') || 'Pending Resolution'
            });
        }
    }
})();
